mapper.select:
select a.auth_id, a.user_id, a.school, a.specialty, a.enrollment_year, a.student_card_id, a.institute, a.org_id, a.position,a.team_leader,
a.employee_code, a.job_time, a.work_card_url, a.post, a.appr_doc_number, a.credit_ident, a.school_cert_url, a.buss_license_num,
a.legal_pers_name, a.legal_id_card, a.buss_license_url, a.certification_type,a.student_card_name,a.work_card_name,a.school_cert_name,
a.buss_license_name,a.check_status, a.company_name,a.is_foreign_student,(select real_name from auth_info where user_id = a.user_id order by auth_time desc limit 1) real_name,
(select id_card from auth_info where user_id = a.user_id order by auth_time desc limit 1) id_card,
a.identity_time,a.create_by, a.create_time, a.update_by, a.update_time, a.version, a.del_flag
from identity_info a
where a.del_flag = '0'

        and a.user_id = #{userId}


    and a.check_status = #{checkStatus}


    and a.certification_type = #{certificationType}


${params.dataScope}
order by a.identity_time desc

select a.auth_id, a.user_id, a.school, nci.school_name,a.specialty, a.enrollment_year, a.student_card_id, a.institute, a.org_id, a.position,a.team_leader, a.employee_code, a.job_time, a.work_card_url, a.post, a.appr_doc_number, a.credit_ident, a.school_cert_url, a.buss_license_num, a.legal_pers_name, a.legal_id_card, a.buss_license_url, a.certification_type,a.student_card_name,a.work_card_name,a.school_cert_name, a.buss_license_name,a.check_status, a.company_name,a.is_foreign_student,(select real_name from auth_info where user_id = a.user_id order by auth_time desc limit 1) real_name, (select id_card from auth_info where user_id = a.user_id order by auth_time desc limit 1) id_card,a.identity_time, a.create_by, a.create_time, a.update_by, a.update_time, a.version, a.del_flag from identity_info a LEFT JOIN nationwide_college_info nci on nci.id = a.school where a.del_flag = '0'
and a.auth_id = #{authId}
and a.certification_type = #{certificationType} and a.check_status not in ('6')
and a.user_id = #{userId}

select count(1) from identity_info
where user_id = #{userId} and del_flag = '0'

    and check_status = #{checkStatus}

mapper.update:
update identity_info
school = #{school}, is_foreign_student = #{isForeignStudent}, team_leader = #{teamLeader}, specialty = #{specialty}, enrollment_year = #{enrollmentYear}, student_card_id = #{studentCardId}, institute = #{institute}, org_id = #{orgId}, position = #{position}, employee_code = #{employeeCode}, job_time = #{jobTime}, work_card_url = #{workCardUrl}, post = #{post}, appr_doc_number = #{apprDocNumber}, credit_ident = #{creditIdent}, school_cert_url = #{schoolCertUrl}, buss_license_num = #{bussLicenseNum}, legal_pers_name = #{legalPersName}, legal_id_card = #{legalIdCard}, buss_license_url = #{bussLicenseUrl}, certification_type = #{certificationType}, student_card_name = #{studentCardName}, work_card_name = #{workCardName}, school_cert_name = #{schoolCertName}, buss_license_name = #{bussLicenseName}, check_status = #{checkStatus}, company_name = #{companyName}, identity_time = #{identityTime}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, version = version+1, del_flag = #{delFlag},
and auth_id = #{authId}
and user_id = #{userId}
